/**
 * DriveGuard — Phase 6 Cross-Language Golden Parity Verification Runner.
 *
 * Reads `scripts/validation/parity_fixtures.json` generated by the authoritative
 * Python reference engine and verifies:
 * 1. Static & rotated 6-DoF fixtures (±25° yaw, -20° pitch, ±15° roll, compound):
 *    - |EAR_diff| <= 1e-4, |MAR_diff| <= 1e-4
 *    - |Euler_diff| <= 1.0° for BOTH 3D landmark Kabsch AND Float32Array(16) matrix paths
 *    - Exact PoseZone equality
 * 2. Multi-frame sequences with calibrated snake_case profile hydration:
 *    - normal_blink, speech_vs_yawn, mirror_distraction_3500ms, nodding_microsleep,
 *      sustained_closure_presets across HIGH | STANDARD | RELAXED
 *    - Exact frame-by-frame operationalState, state, primaryReason, totalBlinks, totalYawns
 * 3. Sensitivity Feature Invariance:
 *    - Raw ear, mar, perclosPct, pitchDeg, yawDeg, rollDeg are bit-for-bit identical (diff === 0)
 *      across RELAXED, STANDARD, and HIGH.
 */

import * as fs from "fs";
import * as path from "path";
import {
  calculateSingleEyeEar,
  calculateYawWeightedEar,
  calculatePitchCompensatedEar,
  calculateMar,
  estimateHeadPoseFromLandmarks,
  DriverFeatureExtractor,
  SignalConfidenceEvaluator,
  TemporalAnalyzer,
  DecisionEngine,
  LEFT_EYE_INDICES,
  RIGHT_EYE_INDICES,
  NormalizedLandmark,
} from "../lib/ai";

interface StaticRef {
  left_ear: number;
  right_ear: number;
  weighted_ear: number;
  compensated_ear: number;
  is_closed: boolean;
  mar: number;
  is_mar_valid: boolean;
  pitch_deg: number;
  yaw_deg: number;
  roll_deg: number;
  zone: string;
  is_valid_pose: boolean;
}

interface SequenceFrameInput {
  timestamp_ms: number;
  landmarks: NormalizedLandmark[];
  facial_matrix_flat: number[];
}

interface SequenceFrameRef {
  timestamp_ms: number;
  ear: number;
  mar: number;
  perclos_pct: number;
  pitch_deg: number;
  yaw_deg: number;
  roll_deg: number;
  zone: string;
  total_blinks: number;
  total_yawns: number;
  is_yawn_in_progress: boolean;
  is_nodding_microsleep: boolean;
  operational_state: string;
  state: string;
  primary_reason: string | null;
}

interface SequenceRunRef {
  sensitivity_level: "HIGH" | "STANDARD" | "RELAXED";
  mirror_suppression_enabled: boolean;
  frames: SequenceFrameRef[];
}

interface FixturePayload {
  frame_width: number;
  frame_height: number;
  calibrated_profile: Record<string, unknown>;
  static_fixtures: Record<
    string,
    {
      landmarks: NormalizedLandmark[];
      facial_matrix_flat: number[];
    }
  >;
  python_reference: Record<string, StaticRef>;
  sequences: Record<
    string,
    {
      frames: SequenceFrameInput[];
      runs: SequenceRunRef[];
    }
  >;
}

async function runParityVerification() {
  const fixturePath = path.resolve(__dirname, "../../scripts/validation/parity_fixtures.json");
  if (!fs.existsSync(fixturePath)) {
    console.error(`Fixture file not found at: ${fixturePath}`);
    process.exit(1);
  }

  const data: FixturePayload = JSON.parse(fs.readFileSync(fixturePath, "utf-8"));
  const frameW = data.frame_width || 640;
  const frameH = data.frame_height || 480;
  const aspectRatio = frameW / frameH;

  let totalAssertions = 0;
  let passedAssertions = 0;
  let maxEarDiff = 0;
  let maxMarDiff = 0;
  let maxEulerDiff = 0;
  const failures: string[] = [];

  const check = (cond: boolean, label: string, detail?: string) => {
    totalAssertions++;
    if (cond) {
      passedAssertions++;
    } else {
      const msg = `${label}${detail ? ` (${detail})` : ""}`;
      failures.push(msg);
      console.error(`  [MISMATCH] ${msg}`);
    }
  };

  console.log("==========================================================================================================");
  console.log("             DRIVEGUARD PHASE 6 CROSS-LANGUAGE GOLDEN PARITY VERIFICATION");
  console.log("==========================================================================================================");

  // ---------------------------------------------------------------------------
  // PART 1: Static & Rotated 6-DoF Fixtures (Kabsch Landmarks + Float32Array(16))
  // ---------------------------------------------------------------------------
  console.log("\n[1/3] Static & Rotated 6-DoF Head-Pose, EAR & MAR Parity...");
  for (const [name, fixture] of Object.entries(data.static_fixtures)) {
    const py = data.python_reference[name];
    if (!py) continue;

    // A. Landmark 3D Kabsch pose estimation
    const poseKabsch = estimateHeadPoseFromLandmarks(
      fixture.landmarks,
      frameW,
      frameH,
      0.0,
      0.0,
      null,
      false
    );
    // B. Float32Array(16) MediaPipe facial transformation matrix pose estimation
    const f32Matrix = new Float32Array(fixture.facial_matrix_flat);
    const poseMatrix = estimateHeadPoseFromLandmarks(
      fixture.landmarks,
      frameW,
      frameH,
      0.0,
      0.0,
      null,
      false,
      null,
      f32Matrix
    );

    const kabschYawDiff = Math.abs(poseKabsch.yawDeg - py.yaw_deg);
    const kabschPitchDiff = Math.abs(poseKabsch.pitchDeg - py.pitch_deg);
    const kabschRollDiff = Math.abs(poseKabsch.rollDeg - py.roll_deg);

    const matYawDiff = Math.abs(poseMatrix.yawDeg - py.yaw_deg);
    const matPitchDiff = Math.abs(poseMatrix.pitchDeg - py.pitch_deg);
    const matRollDiff = Math.abs(poseMatrix.rollDeg - py.roll_deg);

    maxEulerDiff = Math.max(
      maxEulerDiff,
      kabschYawDiff,
      kabschPitchDiff,
      kabschRollDiff,
      matYawDiff,
      matPitchDiff,
      matRollDiff
    );

    check(kabschYawDiff <= 1.0, `${name} Kabsch yaw <= 1.0°`, `TS=${poseKabsch.yawDeg.toFixed(2)} PY=${py.yaw_deg.toFixed(2)}`);
    check(kabschPitchDiff <= 1.0, `${name} Kabsch pitch <= 1.0°`, `TS=${poseKabsch.pitchDeg.toFixed(2)} PY=${py.pitch_deg.toFixed(2)}`);
    check(kabschRollDiff <= 1.0, `${name} Kabsch roll <= 1.0°`, `TS=${poseKabsch.rollDeg.toFixed(2)} PY=${py.roll_deg.toFixed(2)}`);
    check(poseKabsch.zone === py.zone, `${name} Kabsch zone`, `TS=${poseKabsch.zone} PY=${py.zone}`);

    check(matYawDiff <= 1.0, `${name} Float32Array yaw <= 1.0°`, `TS=${poseMatrix.yawDeg.toFixed(2)} PY=${py.yaw_deg.toFixed(2)}`);
    check(matPitchDiff <= 1.0, `${name} Float32Array pitch <= 1.0°`, `TS=${poseMatrix.pitchDeg.toFixed(2)} PY=${py.pitch_deg.toFixed(2)}`);
    check(matRollDiff <= 1.0, `${name} Float32Array roll <= 1.0°`, `TS=${poseMatrix.rollDeg.toFixed(2)} PY=${py.roll_deg.toFixed(2)}`);
    check(poseMatrix.zone === py.zone, `${name} Float32Array zone`, `TS=${poseMatrix.zone} PY=${py.zone}`);

    // EAR & MAR evaluated at the exact reference pose
    const leftEar = calculateSingleEyeEar(fixture.landmarks, LEFT_EYE_INDICES, aspectRatio, true);
    const rightEar = calculateSingleEyeEar(fixture.landmarks, RIGHT_EYE_INDICES, aspectRatio, true);
    const weightedEar = calculateYawWeightedEar(leftEar, rightEar, poseMatrix.yawDeg, true, true, false);
    const compensatedEar = calculatePitchCompensatedEar(weightedEar, poseMatrix.pitchDeg, 0.0, 0.20);
    const mar = calculateMar(fixture.landmarks, aspectRatio, true);

    const earDiff = Math.abs(weightedEar - py.weighted_ear);
    const compDiff = Math.abs(compensatedEar - py.compensated_ear);
    const marDiff = Math.abs(mar - py.mar);
    maxEarDiff = Math.max(maxEarDiff, earDiff, compDiff);
    maxMarDiff = Math.max(maxMarDiff, marDiff);

    check(earDiff <= 1e-4, `${name} weighted EAR <= 1e-4`, `diff=${earDiff.toExponential(2)}`);
    check(compDiff <= 1e-4, `${name} compensated EAR <= 1e-4`, `diff=${compDiff.toExponential(2)}`);
    check(marDiff <= 1e-4, `${name} MAR <= 1e-4`, `diff=${marDiff.toExponential(2)}`);

    console.log(
      `  [OK] ${name.padEnd(15)} | EAR diff=${earDiff.toExponential(1)} | MAR diff=${marDiff.toExponential(1)} | ` +
        `Kabsch maxEuler=${Math.max(kabschYawDiff, kabschPitchDiff, kabschRollDiff).toFixed(3)}° | ` +
        `F32 maxEuler=${Math.max(matYawDiff, matPitchDiff, matRollDiff).toFixed(3)}° | Zone=${poseKabsch.zone}`
    );
  }

  // ---------------------------------------------------------------------------
  // PART 2: Multi-Frame Pipeline Sequences with Snake-Case Profile Hydration
  // ---------------------------------------------------------------------------
  console.log("\n[2/3] Multi-Frame Sequences & Sensitivity Preset Parity...");
  const tsClosureRuns: Array<{ level: string; frames: Array<Record<string, number>> }> = [];

  for (const [seqName, seqData] of Object.entries(data.sequences)) {
    for (const runRef of seqData.runs) {
      const extractor = new DriverFeatureExtractor({
        profile: data.calibrated_profile,
        isMirrored: false,
      });
      const confidenceEval = new SignalConfidenceEvaluator();
      const temporal = new TemporalAnalyzer();
      const decisionEngine = new DecisionEngine({
        sensitivityLevel: runRef.sensitivity_level,
        mirrorSuppressionEnabled: runRef.mirror_suppression_enabled,
      });

      check(
        extractor.isProfileCalibrated && extractor.isProfileFeasible,
        `${seqName}[${runRef.sensitivity_level}] snake_case profile hydration`
      );

      const recordedRawFeatures: Array<Record<string, number>> = [];

      for (let i = 0; i < seqData.frames.length; i++) {
        const frameIn = seqData.frames[i];
        const pyFrame = runRef.frames[i];

        const f32 = new Float32Array(frameIn.facial_matrix_flat);
        const features = extractor.extract(frameIn.landmarks, frameIn.timestamp_ms, frameW, frameH, f32);
        const conf = confidenceEval.evaluate(features, null, {
          isCalibrated: true,
          isCalibrating: false,
        });
        const metrics = temporal.update(features, conf.isReliable, conf.ocularViable);
        const decision = decisionEngine.evaluate(metrics, conf);

        recordedRawFeatures.push({
          ear: features.ear.compensatedEar,
          mar: features.mar.mar,
          perclosPct: features.perclos.perclosPct,
          pitchDeg: features.headPose.pitchDeg,
          yawDeg: features.headPose.yawDeg,
          rollDeg: features.headPose.rollDeg,
        });

        const tag = `${seqName}[${runRef.sensitivity_level},mirror=${runRef.mirror_suppression_enabled}]@t=${frameIn.timestamp_ms}`;
        check(
          Math.abs(features.ear.compensatedEar - pyFrame.ear) <= 1e-4,
          `${tag} ear`,
          `TS=${features.ear.compensatedEar.toFixed(5)} PY=${pyFrame.ear.toFixed(5)}`
        );
        check(
          Math.abs(features.mar.mar - pyFrame.mar) <= 1e-4,
          `${tag} mar`,
          `TS=${features.mar.mar.toFixed(5)} PY=${pyFrame.mar.toFixed(5)}`
        );
        check(features.headPose.zone === pyFrame.zone, `${tag} zone`, `TS=${features.headPose.zone} PY=${pyFrame.zone}`);
        check(
          features.blink.totalBlinkCount === pyFrame.total_blinks,
          `${tag} totalBlinks`,
          `TS=${features.blink.totalBlinkCount} PY=${pyFrame.total_blinks}`
        );
        check(
          features.mar.totalYawnCount === pyFrame.total_yawns,
          `${tag} totalYawns`,
          `TS=${features.mar.totalYawnCount} PY=${pyFrame.total_yawns}`
        );
        check(
          features.mar.isYawnInProgress === pyFrame.is_yawn_in_progress,
          `${tag} isYawnInProgress`,
          `TS=${features.mar.isYawnInProgress} PY=${pyFrame.is_yawn_in_progress}`
        );
        check(
          metrics.isNoddingMicrosleep === pyFrame.is_nodding_microsleep,
          `${tag} isNoddingMicrosleep`,
          `TS=${metrics.isNoddingMicrosleep} PY=${pyFrame.is_nodding_microsleep}`
        );
        check(
          decision.operationalState === pyFrame.operational_state,
          `${tag} operationalState`,
          `TS=${decision.operationalState} PY=${pyFrame.operational_state}`
        );
        check(
          decision.state === pyFrame.state,
          `${tag} state`,
          `TS=${decision.state} PY=${pyFrame.state}`
        );
        const tsPrimaryReason = decision.primaryReason ? decision.primaryReason.code : null;
        check(
          tsPrimaryReason === pyFrame.primary_reason,
          `${tag} primaryReason`,
          `TS=${tsPrimaryReason} PY=${pyFrame.primary_reason}`
        );
      }

      if (seqName === "sustained_closure_presets") {
        tsClosureRuns.push({ level: runRef.sensitivity_level, frames: recordedRawFeatures });
      }

      const lastPy = runRef.frames[runRef.frames.length - 1];
      console.log(
        `  [OK] ${seqName.padEnd(26)} | preset=${runRef.sensitivity_level.padEnd(8)} mirror=${String(runRef.mirror_suppression_enabled).padEnd(5)} | ` +
          `frames=${seqData.frames.length} | final=${lastPy.state} (${lastPy.primary_reason})`
      );
    }
  }

  // ---------------------------------------------------------------------------
  // PART 3: TypeScript Sensitivity Feature Invariance (diff === 0 across presets)
  // ---------------------------------------------------------------------------
  console.log("\n[3/3] Sensitivity Feature Invariance Verification (HIGH vs STANDARD vs RELAXED)...");
  check(tsClosureRuns.length === 3, "Expected 3 sensitivity preset runs for sustained_closure_presets");
  if (tsClosureRuns.length === 3) {
    const base = tsClosureRuns[0].frames;
    for (let r = 1; r < tsClosureRuns.length; r++) {
      const other = tsClosureRuns[r].frames;
      for (let i = 0; i < base.length; i++) {
        for (const k of ["ear", "mar", "perclosPct", "pitchDeg", "yawDeg", "rollDeg"] as const) {
          check(
            base[i][k] === other[i][k],
            `TS feature invariance (${tsClosureRuns[0].level} vs ${tsClosureRuns[r].level}) frame ${i} ${k}`,
            `${base[i][k]} !== ${other[i][k]}`
          );
        }
      }
    }
    console.log("  [OK] Raw ear, mar, perclosPct, pitchDeg, yawDeg, rollDeg are bit-for-bit identical (diff === 0) across all 3 presets.");
  }

  console.log("==========================================================================================================");
  console.log(`Max Observed EAR Diff   : ${maxEarDiff.toExponential(3)} (limit <= 1e-4)`);
  console.log(`Max Observed MAR Diff   : ${maxMarDiff.toExponential(3)} (limit <= 1e-4)`);
  console.log(`Max Observed Euler Diff : ${maxEulerDiff.toFixed(4)}° (limit <= 1.0°)`);
  console.log(
    `Total Golden Parity Assertions Passed: ${passedAssertions}/${totalAssertions} (${((passedAssertions / Math.max(1, totalAssertions)) * 100).toFixed(2)}%)`
  );

  if (failures.length > 0) {
    console.error(`\n[DriveGuard] Cross-language parity verification FAILED (${failures.length} mismatches).`);
    process.exit(1);
  }

  console.log("[DriveGuard] Cross-language Golden Parity CI PASSED 100%!");
}

runParityVerification().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
